RSpec.describe Invoices::PreparedReservations, "abort scope" do
  include PreparedReservationsSpecSupport

  # "Abort drops only this operation's provisional rows. Store the operation identity on each reservation row, so commit and abort touch only their own rows"
  it "abort drops only its own provisional row and keeps another invoice's provisional row and committed row" do
    prepare_local_ownership!
    company = create(:company)
    own_entry = prepared_spec_entry(company)
    other_entry = prepared_spec_entry(company)
    committed_entry = prepared_spec_entry(company)
    invoice = prepared_spec_invoice(company)
    other_invoice = prepared_spec_invoice(company)
    committed_invoice = prepared_spec_invoice(company)
    adapter = described_class.new
    prepared_spec_commit_flow(adapter, prepared_spec_request(company, committed_invoice, [committed_entry.id]))
    shared_operation_id = SecureRandom.uuid
    own_request = prepared_spec_request(company, invoice, [own_entry.id], operation_id: shared_operation_id)
    expect(adapter.prepare(own_request).state).to eq("prepared")
    expect(adapter.prepare(prepared_spec_request(company, other_invoice, [other_entry.id])).state).to eq("prepared")

    expect(adapter.abort(own_request).state).to eq("aborted")

    expect(prepared_spec_reservations(company)).to eq([
      [other_entry.id, other_invoice.id, "provisional", "active"],
      [committed_entry.id, committed_invoice.id, "committed", "active"]
    ].sort)
    expect(prepared_spec_operations(company, invoice).map(&:first)).to eq(["aborted"])
    # Locked, then unlocked again: two snapshots for the entry abort freed.
    expect(prepared_spec_outbox_count(own_entry)).to eq(2)
    expect(Timekeeping::LocalEntry.with_reserved.find(own_entry.id).reserved).to be(false)
  end
end

